class Event {
    constructor() {
        this.ret = null;
    }
}
class EventBus {
    constructor() {
        this.callbacks = {};
    }
    register(name, callback) {
        if (!this.callbacks[name]) {
            this.callbacks[name] = [];
        }
        this.callbacks[name].push(callback);
    }
    fire(name, data) {
        let ret = {};
        if (this.callbacks[name]) {
            this.callbacks[name].forEach(callback => {
                let evt = new Event();
                callback(data, evt);
                if (evt.ret != null) {
                    Object.assign(ret, evt.ret);
                }
            });
        }
        return ret;
    }
}

class Util {
    constructor() {
    }
    static init(main, maingame) {
        this.main = main;
        this.game = maingame;
    }
    static shortName(name) {
        let [f, l] = name.split(" ");
        return `${f}`.toUpperCase();
    }
    static getSide(guy) {
        let side = guy.side._hx_name;
        if (side == "SIDE_RIGHT") return 2;
        else return 1;
    }
    static getOpponent(guy) {
        if (this.getSide(guy) == 2) return guys[0];
        else return guys[1];
    }
    static getFromName(name) {
        // if (guys[0] == null || guys[1] == null) return [];
        let res = [];
        if (this.main.player.firstGuyClassName == name) res.push(guys[1]);
        if (this.main.player.secondGuyClassName == name) res.push(guys[0]);
        return res;
    }
    static addScore(guy, score) {
        let panel = this.game.thisMG.panel;
        guy.score += score;
        if (this.getSide(guy) == 2) panel.lastSideScored = -1;
        else panel.lastSideScored = 1;
        panel.ScoreEvent(score);
    }
    static getTexture(x, y, w, h, BundlerData, INGAME_$PNG, openfl_geom_Rectangle) {
        BundlerData.rect = new openfl_geom_Rectangle(x, y, w, h);
        return INGAME_$PNG.Get();
    }
    static isCritical(guy) {
        return Math.random() < (guy.mCritical - guy.mMissRate) / 100;
    }
    static isMissed(guy) {
        return Math.random() < (guy.mMissRate - guy.mCritical) / 100;
    }
}

